async function wait(ms){await new Promise(r=>setTimeout(r,ms))}
const cell = String(args.cell ?? '').trim();
const values = args.values;
if (!cell) return { error: 'cell required' };
if (!Array.isArray(values) || values.length === 0) return { error: 'values must be a non-empty 2D array' };
if (!values.every(Array.isArray)) return { error: 'values must be a 2D array (each row is an array)' };
const cols = values[0].length;
if (!values.every(r => r.length === cols)) return { error: 'all rows must have the same column count', expected: cols };
// Navigate to top-left
const nb = document.querySelector('#t-name-box');
if (!nb) return { error: 'name box missing — not on a spreadsheet?' };
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
nb.focus();
setter.call(nb, cell);
nb.dispatchEvent(new Event('input', { bubbles: true }));
nb.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
await wait(300);
const editor = document.querySelector('#waffle-rich-text-editor');
if (!editor) return { error: 'rich-text editor missing — paste target gone' };
editor.focus();
await wait(40);
// Build HTML <table>
function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
}
const rowsHtml = values.map(row => '<tr>' + row.map(v => '<td>' + escapeHtml(v ?? '') + '</td>').join('') + '</tr>').join('');
const html = '<table>' + rowsHtml + '</table>';
// Plain-text fallback (tabs/newlines — single-line cells only)
const tsv = values.map(row => row.map(v => String(v ?? '').replace(/\t/g, ' ').replace(/\n/g, ' ')).join('\t')).join('\n');
const dt = new DataTransfer();
dt.setData('text/html', html);
dt.setData('text/plain', tsv);
const evt = new ClipboardEvent('paste', { clipboardData: dt, bubbles: true, cancelable: true });
editor.dispatchEvent(evt);
await wait(500);
return { ok: true, rows: values.length, cols, selection_after: document.querySelector('#t-name-box').value };

async function wait(ms){await new Promise(r=>setTimeout(r,ms))}
const range = String(args.range ?? '').trim();
if (!range) return { error: 'range required' };
const nb = document.querySelector('#t-name-box');
