nb.focus();
setter.call(nb, range);
nb.dispatchEvent(new Event('input', { bubbles: true }));
nb.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
await wait(300);
const editor = document.querySelector('#waffle-rich-text-editor');
if (!editor) return { error: 'editor missing' };
editor.focus();
await wait(40);
for (const type of ['keydown', 'keypress', 'keyup']) {
  editor.dispatchEvent(new KeyboardEvent(type, { key: 'Delete', code: 'Delete', keyCode: 46, which: 46, bubbles: true }));
}
await wait(300);
return { ok: true, cleared: range };

