async function wait(ms){await new Promise(r=>setTimeout(r,ms))}
const btn = document.querySelector('[aria-label="Add Sheet"]');
if (!btn) return { error: 'Add Sheet button not found' };
const before = document.querySelectorAll('.docs-sheet-tab').length;
btn.click();
await wait(600);
const tabs = Array.from(document.querySelectorAll('.docs-sheet-tab'));
const active = tabs.find(t => t.classList.contains('docs-sheet-active-tab'));
return { ok: true, sheet_count: tabs.length, added: tabs.length > before, active_sheet: active?.querySelector('.docs-sheet-tab-name')?.innerText ?? null };
